// dart format width=80
// Generated by `fvm dart run drift_dev make-migrations`, then filled in for
// plan 0005, U2a. The generated/ folder must not be edited by hand.
// ignore_for_file: unused_local_variable, unused_import
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:ever_moon/storage/database/app_database.dart';
import 'package:flutter_test/flutter_test.dart';
import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  // ST-9 (plan 0005, U2a): v1 rows survive and get the v2 defaults.
  test('ST-9 migration from v1 to v2 keeps every row', () async {
    final created = DateTime.utc(2026, 11, 1, 8);
    final seconds = created.millisecondsSinceEpoch ~/ 1000;
    final oldAnniversariesData = <v1.AnniversariesData>[
      v1.AnniversariesData(
        id: 'a1',
        name: 'Ông nội',
        lunarDay: 27,
        lunarMonth: 9,
        deathYear: 2001,
        diedInLeapMonth: 0,
        reminderEnabled: 1,
        note: 'Cúng chay',
        createdAt: seconds,
        updatedAt: seconds,
      ),
      v1.AnniversariesData(
        id: 'a2',
        name: 'Bà nội',
        lunarDay: 9,
        lunarMonth: 10,
        diedInLeapMonth: 0,
        reminderEnabled: 0,
        createdAt: seconds,
        updatedAt: seconds,
        deletedAt: seconds,
      ),
    ];
    final expectedNewAnniversariesData = <v2.AnniversariesData>[
      v2.AnniversariesData(
        id: 'a1',
        name: 'Ông nội',
        lunarDay: 27,
        lunarMonth: 9,
        deathYear: 2001,
        diedInLeapMonth: 0,
        reminderEnabled: 1,
        remindDaysBefore: 0,
        remindMinuteOfDay: 420,
        note: 'Cúng chay',
        createdAt: seconds,
        updatedAt: seconds,
      ),
      v2.AnniversariesData(
        id: 'a2',
        name: 'Bà nội',
        lunarDay: 9,
        lunarMonth: 10,
        diedInLeapMonth: 0,
        reminderEnabled: 0,
        remindDaysBefore: 0,
        remindMinuteOfDay: 420,
        createdAt: seconds,
        updatedAt: seconds,
        deletedAt: seconds,
      ),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch.insertAll(oldDb.anniversaries, oldAnniversariesData);
      },
      validateItems: (newDb) async {
        expect(
          await newDb.select(newDb.anniversaries).get(),
          expectedNewAnniversariesData,
        );
      },
    );
  });
}
